head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// popupUrl 로 지정할 두 가지 값 형태 (같은 내용의 커스텀 팝업 화면을 각각 .html 파일 / .xml 화면으로 준비)
scwin.URL_HTML = "/jira/202608/fail_gridView_advancedExcelUpload_popupUrlFormAsymmetry_popup_html.html";
scwin.URL_XML = "/jira/202608/fail_gridView_advancedExcelUpload_popupUrlFormAsymmetry_popup_xml.xml";

scwin.gVar = null;
scwin.gError = [];



scwin.onpageload = function () {
    // 케이스별 콘솔 오류를 결과창에 함께 출력하기 위해 전역 오류를 수집한다.
    window.addEventListener("error", function (e) {
        scwin.gError.push((e.message === undefined || e.message === null || e.message === "") ? String(e.type) : e.message);
    });
};



// 이전 케이스에서 열린 팝업창 / WFrame 레이어를 닫는다.
//  · WFrame 레이어를 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    try {
        if (scwin.gVar !== null && scwin.gVar.win !== null && scwin.gVar.win.closed === false) scwin.gVar.win.close();
    } catch (e) {}

    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return false;

        WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
        return true;
    } catch (e) {}

    return false;
};



// popupUrl 값 형태와 wframe 조합으로 advancedExcelUpload 실행
//  · 별도 팝업창은 엔진이 호출 시점에 window 이름 fileupWindow 로 생성하므로 그 자리에서 창 핸들을 한 번만 확보한다.
//    (나중에 window.open 으로 창을 다시 찾으면 이미 닫힌 경우 빈 창(about:blank)이 새로 열리므로 확보해 둔 핸들로만 판정한다.)
scwin.runCase = function (strNo, strUrlKind, strPopupUrl, bWframe) {
    var bClosed = scwin.closeOpened();
    scwin.gError = [];
    scwin.gVar = { "no" : strNo, "wframe" : bWframe, "win" : null };

    scwin.setReturnValue("[" + strNo + "] popupUrl = " + strUrlKind + " , wframe = " + bWframe);

    var fnRun = function () {
        var fnOpen = window.open;
        window.open = function (sUrl, sName) {
            var objWin = fnOpen.apply(window, arguments);
            if (sName === "fileupWindow") scwin.gVar.win = objWin;
            return objWin;
        };
        try {
            grd_upload.advancedExcelUpload({ "popupUrl" : strPopupUrl, "wframe" : bWframe });
        } finally {
            window.open = fnOpen;
        }

        setTimeout(function () { scwin.printState(0); }, 1500);
    };

    // 이전 WFrame 레이어의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 실제로 열린 Excel 파일 선택 팝업의 형태 / 경로 / 렌더 여부 / 콘솔 오류 출력
//  · wframe 적용 시 화면 내 레이어(WFrame ID 는 GridView ID + _excelPop_wframe), 미적용 시 window 이름 fileupWindow 인 별도 팝업창이다.
scwin.printState = function (nRetry) {
    nRetry = nRetry || 0;

    var strKind = "";
    var strUrl = "";
    var strText = "";

    if (scwin.gVar.wframe === true) {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame !== null) {
            var objComp = WebSquare.util.getComponentById(objFrame.id);
            strKind = "화면 내 WFrame 레이어";
            strUrl = (objComp === null ? "" : objComp.getSrc());
            strText = objFrame.textContent || "";
        }
    } else {
        var objWin = scwin.gVar.win;
        if (objWin !== null && objWin.closed === false && objWin.location.href !== "about:blank") {
            strKind = "별도 팝업창";
            strUrl = objWin.location.href;
            try {
                strText = (objWin.document.body === null ? "" : objWin.document.body.innerText) || "";
                if (objWin.document.contentType !== "text/html") strKind = strKind + " (문서 형식 " + objWin.document.contentType + ")";
            } catch (e) {}
        }
    }

    // 팝업 생성이 끝나지 않았으면 잠시 뒤 다시 확인한다.
    if (strKind === "" && nRetry < 8) {
        setTimeout(function () { scwin.printState(nRetry + 1); }, 500);
        return;
    }

    strText = strText.replace(/\s+/g, " ").replace(/^ /, "").replace(/ $/, "");
    strUrl = strUrl.split("?")[0];

    scwin.setReturnValue("열린 형태 : " + (strKind === "" ? "없음 (팝업이 확인되지 않음)" : strKind + " - " + strUrl.substring(strUrl.lastIndexOf("/") + 1)));
    scwin.setReturnValue("렌더 내용 : " + (strText === "" ? "없음 (빈 화면)" : (strText.indexOf("CUSTOM POPUP RENDERED") > -1 ? "커스텀 팝업 화면 정상 표시" : strText.substring(0, 60))));

    for (var i = 0; i < scwin.gError.length; i++) {
        scwin.setReturnValue("콘솔 오류 : " + scwin.gError[i]);
    }
    scwin.setReturnValue("");
};



// ① .html 파일 경로 + wframe false
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", ".html 파일 경로", scwin.URL_HTML, false);
};

// ② .html 파일 경로 + wframe true
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", ".html 파일 경로", scwin.URL_HTML, true);
};

// ③ .xml 화면 경로 + wframe true
scwin.btn_case3_onclick = function () {
    scwin.runCase("③", ".xml 화면 경로", scwin.URL_XML, true);
};

// ④ .xml 화면 경로 + wframe false
scwin.btn_case4_onclick = function () {
    scwin.runCase("④", ".xml 화면 경로", scwin.URL_XML, false);
};
